  try{response=await fetch(`/api/staff/native/${path}`,{method:verb,credentials:'same-origin',cache:'no-store',signal:controller.signal,headers:body===undefined?{}:{'content-type':'application/json',...(csrf?{'x-csrf-token':csrf}:{})},body:body===undefined?undefined:JSON.stringify(body)});}catch(error){if(error.name==='AbortError'||controller.signal.aborted)throw new Error('Jaringan terlalu lambat. Data tetap tersimpan di perangkat dan dapat dicoba lagi.');throw new Error('Jaringan terputus. Data tetap tersimpan di perangkat dan dapat dicoba lagi.');}finally{clearTimeout(timer);}
